package am.zzws.admin;
import android.content.Context;import android.content.SharedPreferences;import android.security.keystore.KeyGenParameterSpec;import android.security.keystore.KeyProperties;import android.util.Base64;
import java.nio.charset.StandardCharsets;import java.security.KeyStore;import javax.crypto.Cipher;import javax.crypto.KeyGenerator;import javax.crypto.SecretKey;import javax.crypto.spec.GCMParameterSpec;
/** Only the opaque session token persists, encrypted with a non-exportable per-install key. */
final class SecureSessionStore {
 private static final String ALIAS="zzws_session_v1";private final SharedPreferences preferences;
 SecureSessionStore(Context context){preferences=context.getApplicationContext().getSharedPreferences("zzws_session",Context.MODE_PRIVATE);}
 private SecretKey key() throws Exception {KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias(ALIAS)){KeyGenerator generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setKeySize(256).build());generator.generateKey();}return (SecretKey)store.getKey(ALIAS,null);}
 void save(String endpoint,String token) throws Exception {if(!token.matches("[a-f0-9]{64}"))throw new Exception("Սխալ աշխատաշրջան");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());cipher.updateAAD(endpoint.getBytes(StandardCharsets.UTF_8));String value=Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(token.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP);if(!preferences.edit().putString("ciphertext",value).commit())throw new Exception("Չհաջողվեց պահպանել մուտքը");}
 String read(String endpoint){try{String value=preferences.getString("ciphertext","");if(value.isEmpty())return "";String[] parts=value.split(":",-1);if(parts.length!=2)throw new Exception();Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));cipher.updateAAD(endpoint.getBytes(StandardCharsets.UTF_8));String token=new String(cipher.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),StandardCharsets.UTF_8);if(!token.matches("[a-f0-9]{64}"))throw new Exception();return token;}catch(Exception ignored){clear();return "";}}
 void clear(){preferences.edit().clear().commit();}
}
